const TICKETS_BUCKET = "tickets";
const RECEIPTS_BUCKET = "receipts";

async function sbStorageUpload(path, file, bucket = TICKETS_BUCKET) {
  const res = await fetch(`/api/storage?action=upload&bucket=${bucket}&path=${encodeURIComponent(path)}`, {
    method: "POST",
    headers: {
      "Content-Type": file.type || "application/pdf",
      ...authHeaders(),
    },
    body: file,
  });
  if (!res.ok) {
    const text = await res.text().catch(() => "");
    throw new Error(`Upload échoué — ${res.status} ${text}`);
  }
  return res.json();
}

async function sbStorageDelete(path, bucket = TICKETS_BUCKET) {
  const res = await fetch("/api/storage?action=delete", {
    method: "POST",
    headers: { "Content-Type": "application/json", ...authHeaders() },
    body: JSON.stringify({ bucket, path }),
  });
  if (!res.ok) {
    const text = await res.text().catch(() => "");
    throw new Error(`Suppression échouée — ${res.status} ${text}`);
  }
}

// ---- Rappel quotidien (notification push à 8h) ----
function urlBase64ToUint8Array(base64String) {
  const padding = "=".repeat((4 - (base64String.length % 4)) % 4);
  const base64 = (base64String + padding).replace(/-/g, "+").replace(/_/g, "/");
  const rawData = atob(base64);
  const outputArray = new Uint8Array(rawData.length);
  for (let i = 0; i < rawData.length; i++) outputArray[i] = rawData.charCodeAt(i);
  return outputArray;
}

async function subscribeToDailyReminder(user) {
  if (!("serviceWorker" in navigator) || !("PushManager" in window)) {
    return { ok: false, message: "Les notifications ne sont pas prises en charge sur cet appareil/navigateur." };
  }
  try {
    const registration = await navigator.serviceWorker.register("/sw.js");
    await navigator.serviceWorker.ready;
    const existingSub = await registration.pushManager.getSubscription();

    // Déjà activé sur cet appareil → un second clic désactive.
    if (existingSub) {
      const endpoint = existingSub.endpoint;
      await existingSub.unsubscribe();
      try {
        await sbFetch(`wifi_push_subscriptions?endpoint=eq.${encodeURIComponent(endpoint)}`, { method: "DELETE" });
      } catch (e) {
        console.error(e);
      }
      return { ok: true, active: false, message: "Rappel quotidien désactivé sur cet appareil." };
    }

    const permission = await Notification.requestPermission();
    if (permission !== "granted") {
      return { ok: false, message: "Autorisation refusée — active les notifications dans les réglages du navigateur pour ce site." };
    }
    const sub = await registration.pushManager.subscribe({
      userVisibleOnly: true,
      applicationServerKey: urlBase64ToUint8Array(VAPID_PUBLIC_KEY),
    });
    const json = sub.toJSON();
    await sbFetch("wifi_push_subscriptions?on_conflict=endpoint", {
      method: "POST",
      headers: { Prefer: "resolution=merge-duplicates,return=representation" },
      body: JSON.stringify({
        endpoint: json.endpoint,
        p256dh: json.keys.p256dh,
        auth: json.keys.auth,
        role: user?.role || null,
        nom: user?.nom || null,
      }),
    });
    return { ok: true, active: true, message: "Rappel quotidien de 8h activé sur cet appareil." };
  } catch (e) {
    console.error(e);
    return { ok: false, message: "Erreur lors de l'activation des rappels." };
  }
}

