function todayMidnight() {
  const d = new Date();
  d.setHours(0, 0, 0, 0);
  return d;
}

// Ajoute 1 mois à une date (YYYY-MM-DD) en respectant le calendrier : si le jour n'existe pas
// dans le mois suivant (ex: 31 janvier), on se cale sur le dernier jour de ce mois-là plutôt
// que de déborder sur le mois d'après.
// Ajoute un nombre de jours à une date (YYYY-MM-DD).
function addDaysToDate(dateStr, days) {
  const d = new Date(dateStr + "T00:00:00");
  d.setDate(d.getDate() + days);
  const pad = (n) => String(n).padStart(2, "0");
  return `${d.getFullYear()}-${pad(d.getMonth() + 1)}-${pad(d.getDate())}`;
}

// Ajoute N mois à une date, en respectant le calendrier (comme addOneMonthClamped, généralisé).
function addMonthsClamped(dateStr, months) {
  const d = new Date(dateStr + "T00:00:00");
  const day = d.getDate();
  const totalMonths = d.getFullYear() * 12 + d.getMonth() + months;
  const targetYear = Math.floor(totalMonths / 12);
  const targetMonth = ((totalMonths % 12) + 12) % 12;
  const lastDayOfTargetMonth = new Date(targetYear, targetMonth + 1, 0).getDate();
  const newDay = Math.min(day, lastDayOfTargetMonth);
  const newDate = new Date(targetYear, targetMonth, newDay);
  const pad = (n) => String(n).padStart(2, "0");
  return `${newDate.getFullYear()}-${pad(newDate.getMonth() + 1)}-${pad(newDate.getDate())}`;
}

// Calcule la nouvelle échéance après un bonus (jours/semaines/mois), à partir de l'échéance
// actuelle si elle n'est pas encore dépassée, sinon à partir d'aujourd'hui.
function computeBonusExpiration(currentDateExp, amount, unit) {
  const t = todayMidnight();
  const pad = (n) => String(n).padStart(2, "0");
  const todayStr = `${t.getFullYear()}-${pad(t.getMonth() + 1)}-${pad(t.getDate())}`;
  const base = !currentDateExp ? todayStr : (computeStatus(currentDateExp).statut === "EXPIRE" ? todayStr : currentDateExp);
  if (unit === "jour") return addDaysToDate(base, amount);
  if (unit === "semaine") return addDaysToDate(base, amount * 7);
  if (unit === "mois") return addMonthsClamped(base, amount);
  return base;
}

function addOneMonthClamped(dateStr) {
  const d = new Date(dateStr + "T00:00:00");
  const day = d.getDate();
  const totalMonths = d.getFullYear() * 12 + d.getMonth() + 1;
  const targetYear = Math.floor(totalMonths / 12);
  const targetMonth = totalMonths % 12;
  const lastDayOfTargetMonth = new Date(targetYear, targetMonth + 1, 0).getDate();
  const newDay = Math.min(day, lastDayOfTargetMonth);
  const newDate = new Date(targetYear, targetMonth, newDay);
  const pad = (n) => String(n).padStart(2, "0");
  return `${newDate.getFullYear()}-${pad(newDate.getMonth() + 1)}-${pad(newDate.getDate())}`;
}

const ARCHIVE_AFTER_MS = 7 * 24 * 60 * 60 * 1000; // 1 semaine
function isComplaintArchived(c) {
  return c.status === "resolu" && c.resolvedAt && Date.now() - new Date(c.resolvedAt).getTime() > ARCHIVE_AFTER_MS;
}
function matchesComplaintFilter(c, complaintFilter) {
  if (complaintFilter === "archived") return isComplaintArchived(c);
  if (isComplaintArchived(c)) return false; // les réclamations archivées sortent des autres catégories
  if (complaintFilter === "ALL") return true;
  return c.status === complaintFilter;
}

function computeStatus(dateExp) {
  if (!dateExp) return { jours: null, statut: "NA", action: "—" };
  const exp = new Date(dateExp + "T00:00:00");
  if (isNaN(exp.getTime())) return { jours: null, statut: "NA", action: "Date invalide" };
  const jours = Math.round((exp - todayMidnight()) / 86400000);
  if (jours < 0) return { jours, statut: "EXPIRE", action: "déjà coupé" };
  if (jours === 0) return { jours, statut: "ATTENTION", action: "À COUPER" };
  if (jours <= 2) return { jours, statut: "ATTENTION", action: "2ème notification" };
  if (jours < 5) return { jours, statut: "ATTENTION", action: "Notifier" };
  return { jours, statut: "OK", action: "ok" };
}

// Règle commune de renouvellement (clients ET lignes de dépenses) : si l'échéance n'est pas
// encore dépassée, on prolonge d'1 mois à partir d'elle. Si elle est déjà expirée, on repart
// d'1 mois à partir d'aujourd'hui (date du réabonnement), pas de l'ancienne échéance dépassée.
function computeRenewedExpiration(currentDateExp) {
  const todayStr = (() => {
    const t = todayMidnight();
    const pad = (n) => String(n).padStart(2, "0");
    return `${t.getFullYear()}-${pad(t.getMonth() + 1)}-${pad(t.getDate())}`;
  })();
  if (!currentDateExp) return addOneMonthClamped(todayStr);
  const { statut } = computeStatus(currentDateExp);
  const base = statut === "EXPIRE" ? todayStr : currentDateExp;
  return addOneMonthClamped(base);
}

// Même règle, mais pour un paiement soumis via l'application : si l'abonnement était déjà
// expiré, on part de la date de SOUMISSION de la demande (pas du jour où l'admin la valide,
// qui peut être plus tardif).
function computeRenewedExpirationFromRequest(currentDateExp, requestCreatedAt) {
  const requestDateStr = requestCreatedAt ? requestCreatedAt.slice(0, 10) : null;
  if (!currentDateExp) return addOneMonthClamped(requestDateStr || computeRenewedExpiration(null));
  const { statut } = computeStatus(currentDateExp);
  if (statut !== "EXPIRE") return addOneMonthClamped(currentDateExp);
  const base = requestDateStr || (() => {
    const t = todayMidnight();
    const pad = (n) => String(n).padStart(2, "0");
    return `${t.getFullYear()}-${pad(t.getMonth() + 1)}-${pad(t.getDate())}`;
  })();
  return addOneMonthClamped(base);
}

// Recule une date d'un jour (format YYYY-MM-DD).
function subtractOneDay(dateStr) {
  const d = new Date(dateStr + "T00:00:00");
  d.setDate(d.getDate() - 1);
  const pad = (n) => String(n).padStart(2, "0");
  return `${d.getFullYear()}-${pad(d.getMonth() + 1)}-${pad(d.getDate())}`;
}

// Règle spécifique aux Lignes (abonnements FAI) : l'échéance suivante est 1 mois moins 1 jour,
// pas 1 mois complet. Ne s'applique pas au réabonnement client, qui reste sur 1 mois plein.
function computeRenewedExpirationLigne(currentDateExp) {
  const { statut } = computeStatus(currentDateExp);
  // Ligne sans échéance ou déjà expirée : la nouvelle période démarre
  // aujourd'hui et se termine 1 mois plus tard moins 1 jour.
  if (!currentDateExp || statut === "EXPIRE") {
    return subtractOneDay(computeRenewedExpiration(currentDateExp));
  }
  // Ligne encore active : la période suivante démarre le LENDEMAIN de l'échéance
  // actuelle et court « 1 mois moins 1 jour » → fin = (échéance + 1 j) + 1 mois − 1 j.
  // On NE fait PAS addOneMonthClamped(échéance) directement : pour une échéance
  // en fin de mois court (le 30, ou février), cela « perd » un jour à chaque
  // renouvellement (ex. 30 sept. → 30 oct. au lieu du 31 oct.) et dérive.
  const debutPeriodeSuivante = addDaysToDate(currentDateExp, 1);
  return subtractOneDay(addOneMonthClamped(debutPeriodeSuivante));
}

function fmtDate(dateExp) {
  if (!dateExp) return "—";
  const d = new Date(dateExp + "T00:00:00");
  if (isNaN(d.getTime())) return "invalide";
  return d.toLocaleDateString("fr-FR", { day: "2-digit", month: "2-digit", year: "numeric" });
}

// Salutation selon l'heure : "Bonjour" le matin/journée, "Bonsoir" à partir de 18h.
function greeting() {
  const h = new Date().getHours();
  return h >= 18 || h < 5 ? "Bonsoir" : "Bonjour";
}

function fmtFCFA(n) {
  return (Number(n) || 0).toLocaleString("fr-FR") + " F";
}

// Distance à vol d'oiseau entre deux points GPS (km) — approximation, pas un itinéraire routier réel.
function haversineKm(lat1, lon1, lat2, lon2) {
  const R = 6371;
  const toRad = (d) => (d * Math.PI) / 180;
  const dLat = toRad(lat2 - lat1);
  const dLon = toRad(lon2 - lon1);
  const a = Math.sin(dLat / 2) ** 2 + Math.cos(toRad(lat1)) * Math.cos(toRad(lat2)) * Math.sin(dLon / 2) ** 2;
  return R * 2 * Math.atan2(Math.sqrt(a), Math.sqrt(1 - a));
}
const DEFAULT_FUEL_RATE_PER_KM = 200; // FCFA/km — valeur par défaut, modifiable par l'admin

// Génère un reçu PDF pour un paiement, retourné sous forme de Blob prêt à uploader.
// fmtFCFA utilise l'espace insécable fine du format fr-FR, absente de la police PDF de base
// (elle s'affichait comme "/"). On reformate ici avec un espace normal, PDF uniquement.
function fmtFCFAForPdf(n) {
  const num = Math.round(Number(n) || 0);
  return String(num).replace(/\B(?=(\d{3})+(?!\d))/g, " ") + " F";
}

// Détecte un vrai téléphone / tablette (pas un ordinateur). Sur PC, même quand
// le navigateur supporte le partage natif (Edge/Windows), on ne veut PAS ouvrir
// le menu « Partager » (qui ne propose que téléphone/WhatsApp) : un simple
// téléchargement est attendu, et l'utilisateur imprime ensuite depuis le PDF.
function estAppareilMobile() {
  if (typeof navigator === "undefined") return false;
  try {
    if (navigator.userAgentData && typeof navigator.userAgentData.mobile === "boolean") {
      return navigator.userAgentData.mobile;
    }
  } catch { /* userAgentData indisponible */ }
  return /Android|iPhone|iPad|iPod|Mobile|Windows Phone/i.test(navigator.userAgent || "");
}

// Remet un PDF entre les mains de l'utilisateur de la façon la PLUS visible
// selon l'appareil :
//  1. Sur téléphone : le menu de PARTAGE natif (« Enregistrer dans Fichiers »,
//     « Envoyer sur WhatsApp »...) — l'utilisateur choisit où va le fichier,
//     au lieu d'un téléchargement invisible qu'on ne retrouve pas.
//  2. Sur ordinateur : téléchargement classique dans le dossier Téléchargements
//     (on n'ouvre jamais le menu « Partager » de Windows).
// Renvoie "shared", "downloaded" ou "cancelled".
async function deliverPdf(blob, fileName, title) {
  const pdf = blob.type === "application/pdf" ? blob : new Blob([blob], { type: "application/pdf" });
  try {
    const file = new File([pdf], fileName, { type: "application/pdf" });
    if (estAppareilMobile() && typeof navigator !== "undefined" && navigator.canShare && navigator.canShare({ files: [file] })) {
      try {
        await navigator.share({ files: [file], title: title || fileName });
        return "shared";
      } catch (e) {
        if (e && e.name === "AbortError") return "cancelled"; // l'utilisateur a fermé le menu
        // autre erreur : on retombe sur le téléchargement classique
      }
    }
  } catch { /* File non supporté : téléchargement classique */ }

  const blobUrl = URL.createObjectURL(pdf);
  const a = document.createElement("a");
  a.href = blobUrl;
  a.download = fileName;
  document.body.appendChild(a);
  a.click();
  document.body.removeChild(a);
  setTimeout(() => URL.revokeObjectURL(blobUrl), 10000);
  return "downloaded";
}

// Nom de fichier lisible pour le reçu : "Recu-NOM-DU-CLIENT-2026-08-20.pdf"
// au lieu d'un code technique. On retire les caractères interdits dans un nom
// de fichier tout en gardant les accents.
function receiptFileName(payment) {
  const nom = (payment.clientNom || "client")
    .replace(/[\\/:*?"<>|]+/g, " ")
    .trim()
    .replace(/\s+/g, "-") || "client";
  const d = payment.date ? `-${payment.date}` : "";
  return `Recu-${nom}${d}.pdf`;
}

async function generateReceiptPDF(payment) {
  // jsPDF chargé seulement au moment de générer un reçu (allège le
  // demarrage de l'app, surtout sur mobile).
  const { default: jsPDF } = await import("jspdf");
  const doc = new jsPDF({ unit: "mm", format: "a5" });
  const pageWidth = doc.internal.pageSize.getWidth();
  const marginX = 15;
  const tableWidth = pageWidth - marginX * 2;

  // ---- En-tête clair ----
  doc.setTextColor(20, 30, 42);
  doc.setFont("helvetica", "bold");
  doc.setFontSize(18);
  doc.text("APESPOT WI-FI", pageWidth / 2, 18, { align: "center" });

  doc.setFont("helvetica", "normal");
  doc.setFontSize(10);
  doc.setTextColor(110, 120, 130);
  doc.text("Reçu de paiement", pageWidth / 2, 25, { align: "center" });

  doc.setDrawColor(62, 216, 195); // accent cyan de l'app
  doc.setLineWidth(0.8);
  doc.line(pageWidth / 2 - 16, 29, pageWidth / 2 + 16, 29);

  // ---- Tableau ----
  const rows = [
    ["Client", payment.clientNom || "—"],
    ["Montant", fmtFCFAForPdf(payment.montant)],
    ["Mode de paiement", payment.mode || "—"],
    ["Date", fmtDate(payment.date)],
  ];
  if (payment.newExpiration) rows.push(["Abonnement valable jusqu'au", fmtDate(payment.newExpiration)]);
  if (payment.note) rows.push(["Référence", payment.note]);
  rows.push(["N° de reçu", payment.id ? payment.id.slice(0, 8).toUpperCase() : "—"]);

  const rowH = 11;
  const colLabelW = tableWidth * 0.46;
  let y = 42;

  doc.setDrawColor(210, 216, 224);
  doc.setLineWidth(0.25);

  rows.forEach((row, i) => {
    const rowY = y + i * rowH;
    if (i % 2 === 0) {
      doc.setFillColor(244, 247, 250);
      doc.rect(marginX, rowY, tableWidth, rowH, "F");
    }
    doc.line(marginX, rowY, marginX + tableWidth, rowY);
    doc.line(marginX + colLabelW, rowY, marginX + colLabelW, rowY + rowH);

    doc.setFont("helvetica", "bold");
    doc.setFontSize(9.5);
    doc.setTextColor(40, 48, 58);
    doc.text(row[0], marginX + 4, rowY + rowH / 2 + 1.3, { maxWidth: colLabelW - 6 });

    doc.setFont("helvetica", "normal");
    doc.setTextColor(20, 20, 20);
    doc.text(String(row[1]), marginX + colLabelW + 4, rowY + rowH / 2 + 1.3, { maxWidth: tableWidth - colLabelW - 8 });
  });

  const tableBottom = y + rows.length * rowH;
  doc.line(marginX, tableBottom, marginX + tableWidth, tableBottom);
  doc.rect(marginX, y, tableWidth, rows.length * rowH);

  doc.setFontSize(8.5);
  doc.setTextColor(140, 148, 158);
  doc.setFont("helvetica", "italic");
  doc.text("Merci de votre confiance — APESPOT WI-FI", pageWidth / 2, tableBottom + 12, { align: "center" });

  return doc.output("blob");
}

// Bilan comptable mensuel en PDF réel (jsPDF), au lieu de window.print() dont
// le rendu sur mobile chevauchait les tableaux. Multi-pages, en-têtes répétés.
async function generateBilanPDF(bilanData, monthLabel, totalClients) {
  const { default: jsPDF } = await import("jspdf");
  const doc = new jsPDF({ unit: "mm", format: "a4" });
  const pageW = doc.internal.pageSize.getWidth();
  const pageH = doc.internal.pageSize.getHeight();
  const marginX = 15;
  const contentW = pageW - marginX * 2;
  const bottomLimit = pageH - 18;
  let y = 0;

  const INK = [14, 21, 32], MUTE = [92, 108, 126], RED = [179, 38, 30];
  const LINE = [226, 230, 235], ZEBRA = [244, 246, 248], HEAD = [244, 246, 248];

  const newPage = () => { doc.addPage(); y = 18; };
  const ensure = (h) => { if (y + h > bottomLimit) newPage(); };

  // ---- En-tête (page 1) ----
  y = 18;
  doc.setTextColor(...INK); doc.setFont("helvetica", "bold"); doc.setFontSize(18);
  doc.text("APESPOT WI-FI", pageW / 2, y, { align: "center" });
  y += 6;
  doc.setFont("helvetica", "normal"); doc.setFontSize(11); doc.setTextColor(...MUTE);
  doc.text("Bilan comptable mensuel", pageW / 2, y, { align: "center" });
  y += 5;
  doc.setFontSize(9.5);
  const dateGen = new Date().toLocaleDateString("fr-FR", { day: "2-digit", month: "2-digit", year: "numeric" });
  doc.text(`Période : ${monthLabel}  ·  Généré le ${dateGen}`, pageW / 2, y, { align: "center" });
  y += 5;
  doc.setDrawColor(62, 216, 195); doc.setLineWidth(0.8);
  doc.line(pageW / 2 - 18, y, pageW / 2 + 18, y);
  y += 10;

  // ---- Cartes résumé (2 lignes de 2) ----
  const cards = [
    [fmtFCFAForPdf(bilanData.total), "Total encaissé"],
    [String(bilanData.count), "Paiements"],
    [fmtFCFAForPdf(bilanData.avg), "Montant moyen"],
    [String(totalClients), "Clients au total"],
  ];
  const cardW = (contentW - 8) / 2, cardH = 16;
  cards.forEach(([n, l], i) => {
    const cx = marginX + (i % 2) * (cardW + 8);
    const cy = y + Math.floor(i / 2) * (cardH + 6);
    doc.setDrawColor(...LINE); doc.setLineWidth(0.3);
    doc.roundedRect(cx, cy, cardW, cardH, 2, 2);
    doc.setFont("helvetica", "bold"); doc.setFontSize(14); doc.setTextColor(...INK);
    doc.text(n, cx + 5, cy + 8);
    doc.setFont("helvetica", "normal"); doc.setFontSize(8.5); doc.setTextColor(...MUTE);
    doc.text(l.toUpperCase(), cx + 5, cy + 13);
  });
  y += cardH * 2 + 6 + 8;

  // ---- Rendu d'une section titrée avec tableau paginé ----
  const sectionTitle = (title) => {
    ensure(14);
    doc.setFont("helvetica", "bold"); doc.setFontSize(10); doc.setTextColor(...MUTE);
    doc.text(title.toUpperCase(), marginX, y);
    y += 2;
    doc.setDrawColor(...LINE); doc.setLineWidth(0.3);
    doc.line(marginX, y, marginX + contentW, y);
    y += 5;
  };

  // cols: [{ w (0..1 of contentW), align, header }]
  const table = (cols, rows, { totalRow } = {}) => {
    const rowH = 8, headH = 8;
    const xs = []; let acc = marginX;
    cols.forEach((c) => { xs.push(acc); acc += c.w * contentW; });
    const drawHeader = () => {
      doc.setFillColor(...HEAD); doc.rect(marginX, y, contentW, headH, "F");
      doc.setFont("helvetica", "bold"); doc.setFontSize(8.5); doc.setTextColor(...MUTE);
      cols.forEach((c, i) => {
        const tx = c.align === "right" ? xs[i] + c.w * contentW - 3 : xs[i] + 3;
        doc.text(c.header.toUpperCase(), tx, y + 5.4, { align: c.align === "right" ? "right" : "left" });
      });
      doc.setDrawColor(...LINE); doc.setLineWidth(0.3);
      doc.line(marginX, y + headH, marginX + contentW, y + headH);
      y += headH;
    };
    ensure(headH + rowH);
    drawHeader();
    const drawRow = (cells, { bold, fill } = {}) => {
      if (y + rowH > bottomLimit) { newPage(); drawHeader(); }
      if (fill) { doc.setFillColor(...ZEBRA); doc.rect(marginX, y, contentW, rowH, "F"); }
      doc.setFont("helvetica", bold ? "bold" : "normal"); doc.setFontSize(8.5);
      cells.forEach((cell, i) => {
        doc.setTextColor(...(cell.color || INK));
        const c = cols[i];
        const tx = c.align === "right" ? xs[i] + c.w * contentW - 3 : xs[i] + 3;
        const maxW = c.w * contentW - 6;
        doc.text(String(cell.t), tx, y + 5.3, { align: c.align === "right" ? "right" : "left", maxWidth: maxW });
      });
      doc.setDrawColor(...LINE); doc.setLineWidth(0.2);
      doc.line(marginX, y + rowH, marginX + contentW, y + rowH);
      y += rowH;
    };
    rows.forEach((r, i) => drawRow(r, { fill: i % 2 === 0 }));
    if (totalRow) drawRow(totalRow, { bold: true, fill: true });
    y += 8;
  };

  // ---- Répartition par mode ----
  sectionTitle("Répartition par mode de paiement");
  const modeCols = [
    { w: 0.40, header: "Mode" },
    { w: 0.15, header: "Nb", align: "right" },
    { w: 0.27, header: "Montant", align: "right" },
    { w: 0.18, header: "Part", align: "right" },
  ];
  if (bilanData.byMode.length === 0) {
    table(modeCols, [[{ t: "Aucun paiement enregistré pour ce mois.", color: MUTE }, { t: "" }, { t: "" }, { t: "" }]]);
  } else {
    table(
      modeCols,
      bilanData.byMode.map((r) => [
        { t: r.mode }, { t: r.count, align: "right" },
        { t: fmtFCFAForPdf(r.sum) },
        { t: (bilanData.total ? Math.round((r.sum / bilanData.total) * 100) : 0) + "%" },
      ]),
      { totalRow: [{ t: "Total" }, { t: bilanData.count }, { t: fmtFCFAForPdf(bilanData.total) }, { t: "100%" }] }
    );
  }

  // ---- Charges & bénéfice net ----
  sectionTitle("Charges & bénéfice net");
  const chargeCols = [{ w: 0.70, header: "Poste" }, { w: 0.30, header: "Montant", align: "right" }];
  table(chargeCols, [
    [{ t: "Total encaissé (abonnements)" }, { t: fmtFCFAForPdf(bilanData.total) }],
    [{ t: `Carburant technicien (${bilanData.fuelCount} déplacement${bilanData.fuelCount > 1 ? "s" : ""})` }, { t: "- " + fmtFCFAForPdf(bilanData.fuelTotal), color: RED }],
    [{ t: `Lignes (${bilanData.lignesCount} ligne${bilanData.lignesCount > 1 ? "s" : ""} active${bilanData.lignesCount > 1 ? "s" : ""})` }, { t: "- " + fmtFCFAForPdf(bilanData.lignesMonthTotal), color: RED }],
    [{ t: `Perdiem (${bilanData.perdiemCount} versement${bilanData.perdiemCount > 1 ? "s" : ""})` }, { t: "- " + fmtFCFAForPdf(bilanData.perdiemMonthTotal), color: RED }],
    [{ t: `Autres dépenses (${bilanData.autresCount})` }, { t: "- " + fmtFCFAForPdf(bilanData.autresMonthTotal), color: RED }],
  ], { totalRow: [{ t: "Bénéfice net du mois" }, { t: fmtFCFAForPdf(bilanData.netBenefit) }] });

  // ---- Détail des paiements ----
  sectionTitle("Détail des paiements du mois");
  const payCols = [
    { w: 0.16, header: "Date" },
    { w: 0.30, header: "Client" },
    { w: 0.20, header: "Mode" },
    { w: 0.18, header: "Montant", align: "right" },
    { w: 0.16, header: "Note" },
  ];
  if (bilanData.sorted.length === 0) {
    table(payCols, [[{ t: "Aucun paiement enregistré pour ce mois.", color: MUTE }, { t: "" }, { t: "" }, { t: "" }, { t: "" }]]);
  } else {
    table(payCols, bilanData.sorted.map((p) => [
      { t: fmtDate(p.date) }, { t: p.clientNom || "-" }, { t: p.mode || "-" },
      { t: fmtFCFAForPdf(p.montant), align: "right" }, { t: p.note || "-" },
    ]));
  }

  // ---- État du parc ----
  sectionTitle("État du parc clients WiFi (à la date de génération)");
  const parcCols = [{ w: 0.70, header: "Statut" }, { w: 0.30, header: "Nombre", align: "right" }];
  table(parcCols, [
    [{ t: "Expirés" }, { t: bilanData.nbExpire }],
    [{ t: "À surveiller" }, { t: bilanData.nbAttention }],
    [{ t: "À jour" }, { t: bilanData.nbOk }],
  ], { totalRow: [{ t: "Total clients" }, { t: totalClients }] });

  // ---- Pied de page sur chaque page ----
  const pages = doc.internal.getNumberOfPages();
  for (let i = 1; i <= pages; i++) {
    doc.setPage(i);
    doc.setFont("helvetica", "italic"); doc.setFontSize(8); doc.setTextColor(...MUTE);
    doc.text("APESPOT WI-FI · Document généré automatiquement", pageW / 2, pageH - 10, { align: "center" });
    doc.text(`Page ${i} / ${pages}`, pageW - marginX, pageH - 10, { align: "right" });
  }

  return doc.output("blob");
}

function normalizePhone(raw) {
  let d = (raw || "").replace(/[^\d]/g, "");
  if (!d) return "";
  if (d.startsWith("00")) d = d.slice(2);
  if (d.length === 8) return "228" + d; // numéro local togolais sans indicatif
  return d; // suppose que l'indicatif est déjà inclus
}

// Ouvre WhatsApp de façon fiable. window.open(_blank) est souvent bloqué sur
// mobile (le nouvel onglet ne s'ouvre pas → « rien ne se passe ») : on bascule
// alors dans l'onglet courant, ce qui lance WhatsApp à coup sûr.
function ouvrirWhatsApp(url) {
  let w = null;
  try { w = window.open(url, "_blank"); } catch { w = null; }
  if (!w || w.closed || typeof w.closed === "undefined") {
    window.location.href = url;
  }
}

// Récupère la position de façon FIABLE, surtout en intérieur (chez le client,
// près du routeur) où le GPS haute précision peut dépasser 10 s. On tente
// d'abord la haute précision avec un délai généreux ; si ça échoue/traîne, on
// retombe sur une localisation réseau/cellule (moins précise mais rapide) au
// lieu d'abandonner. Renvoie une Promise<GeolocationPosition>.
function obtenirPositionFiable() {
  return new Promise((resolve, reject) => {
    if (typeof navigator === "undefined" || !navigator.geolocation) {
      reject({ code: 0, message: "Géolocalisation indisponible" });
      return;
    }
    navigator.geolocation.getCurrentPosition(
      resolve,
      (err1) => {
        // 2e essai plus permissif : réseau/cellule, tolère un point récent
        // (mieux qu'un échec total en intérieur).
        navigator.geolocation.getCurrentPosition(
          resolve,
          () => reject(err1),
          { enableHighAccuracy: false, timeout: 12000, maximumAge: 60000 }
        );
      },
      // Primaire : position FRAÎCHE et haute précision (maximumAge 0), avec un
      // délai généreux pour laisser le temps au GPS de capter en intérieur.
      // Fraîche = pas de risque de récupérer une position « prise ailleurs ».
      { enableHighAccuracy: true, timeout: 20000, maximumAge: 0 }
    );
  });
}

// Message clair selon le code d'erreur de géolocalisation.
function messageErreurGeoloc(err) {
  if (err && err.code === 1) return "Autorisation de localisation refusée — active-la pour l'application dans les réglages du navigateur.";
  if (err && err.code === 2) return "Position indisponible — vérifie que le GPS du téléphone est activé.";
  if (err && err.code === 3) return "Le GPS met trop de temps — réessaie près d'une fenêtre ou en extérieur.";
  return "Impossible de récupérer ta position. Vérifie que la localisation est activée.";
}

function buildWaMessage(c) {
  const { jours, statut } = computeStatus(c.dateExp);
  const dateTxt = fmtDate(c.dateExp);

  let statusLines;
  if (statut === "EXPIRE") {
    statusLines = `Votre abonnement WiFi APESPOT a *expiré le ${dateTxt}*\nMerci de renouveler pour rétablir votre connexion.`;
  } else if (statut === "ATTENTION") {
    statusLines = jours === 0
      ? `Votre abonnement WiFi APESPOT *expire aujourd'hui* (${dateTxt})\nMerci de renouveler rapidement pour éviter une coupure.`
      : `Votre abonnement WiFi APESPOT expire le *${dateTxt}* (dans ${jours} jour${jours > 1 ? "s" : ""})\nMerci de prévoir le renouvellement.`;
  } else if (statut === "OK") {
    statusLines = `Votre abonnement WiFi APESPOT est à jour jusqu'au *${dateTxt}*\nMerci de votre confiance !`;
  } else {
    statusLines = `Ceci est un message de APESPOT WI-FI concernant votre abonnement WiFi.`;
  }

  const closing = statut === "OK"
    ? "Accède à ton espace Pour discuter avec nous, payer ou faire une réclamation"
    : "Accède à ton espace pour payer ou soumettre une réclamation";

  const codeLine = c.accessCode ? `TON CODE : ${c.accessCode}` : "(demande ton code à APESPOT WI-FI)";

  return [
    `${greeting()} ${c.nom}`,
    ``,
    statusLines,
    ``,
    `Click sur : `,
    ``,
    `https://apespot-wifi.vercel.app`,
    ``,
    `Vas sur *client* `,
    ``,
    codeLine,
    ``,
    closing,
  ].join("\n");
}

function loadLocal(key, fallback) {
  try {
    const raw = localStorage.getItem(key);
    if (raw) return JSON.parse(raw);
  } catch (e) {
    /* ignore */
  }
  return fallback;
}

function saveLocal(key, value) {
  try {
    localStorage.setItem(key, JSON.stringify(value));
  } catch (e) {
    /* storage full or unavailable */
  }
}

// ---- Supabase mapping helpers (DB uses snake_case, app state uses camelCase) ----
const rowToClient = (r) => ({ id: r.id, nom: r.nom, offre: r.offre, telephone: r.telephone, serveur: r.serveur, latitude: r.latitude, longitude: r.longitude, dateExp: r.date_exp, previousDateExp: r.previous_date_exp, renewedAt: r.renewed_at, accessCode: r.access_code, relanceLe: r.relance_le });
