// -------------------- Small reusable bits --------------------

function SignalBars({ statut }) {
  const cls =
    statut === "EXPIRE" ? "red" : statut === "ATTENTION" ? "amber" : statut === "OK" ? "green" : "na";
  return (
    <span className={`signal ${cls}`}>
      <i /><i /><i /><i />
    </span>
  );
}

function Badge({ statut }) {
  return <span className={`badge ${statut}`}>{statut === "NA" ? "N/A" : statut}</span>;
}

function NewComplaintModal({ newComplaintModal, setNewComplaintModal, clients, saveNewComplaint }) {
  if (!newComplaintModal) return null;
  const client = clients.find((c) => c.nom.trim().toLowerCase() === (newComplaintModal.clientNom || "").trim().toLowerCase());
  return (
    <div className="overlay show" onClick={(e) => e.target.classList.contains("overlay") && setNewComplaintModal(null)}>
      <div className="modal">
        <h2 style={{ color: "#FFFFFF", fontWeight: 700 }}>Nouvelle réclamation</h2>
        <div style={{ fontSize: 11.5, color: "var(--text-faint)", marginBottom: 14 }}>
          Pour une intervention signalée hors application (appel, en personne...).
        </div>
        <div className="field">
          <label>Client</label>
          <input
            list="newComplaintClientsList"
            placeholder="Tape ou choisis un client"
            autoComplete="off"
            value={newComplaintModal.clientNom || ""}
            onChange={(e) => setNewComplaintModal({ ...newComplaintModal, clientNom: e.target.value })}
          />
          <datalist id="newComplaintClientsList">
            {clients.map((c) => <option key={c.id} value={c.nom} />)}
          </datalist>
          {newComplaintModal.clientNom && (
            <div style={{ fontSize: 11, color: client?.latitude != null ? "var(--green)" : "var(--amber)", marginTop: 6 }}>
              {client
                ? (client.latitude != null ? "✓ Position connue pour ce client" : "⚠ Aucune position connue — le carburant ne pourra pas être calculé sans elle")
                : "Nouveau nom — aucune fiche client correspondante trouvée"}
            </div>
          )}
        </div>
        <div className="field">
          <label>Motif</label>
          <input placeholder="Ex: Connexion lente" value={newComplaintModal.reason || ""} onChange={(e) => setNewComplaintModal({ ...newComplaintModal, reason: e.target.value })} />
        </div>
        <div className="field">
          <label>Depuis le (optionnel)</label>
          <DatePickerInput value={newComplaintModal.dateDebut} onChange={(e) => setNewComplaintModal({ ...newComplaintModal, dateDebut: e.target.value })} />
        </div>
        <div className="field">
          <label>Description (optionnel)</label>
          <textarea rows={3} placeholder="Détails de l'intervention à prévoir..." value={newComplaintModal.description || ""} onChange={(e) => setNewComplaintModal({ ...newComplaintModal, description: e.target.value })} />
        </div>
        <div className="modal-actions">
          <button className="btn-cancel" onClick={() => setNewComplaintModal(null)}>Annuler</button>
          <button className="btn-save" onClick={saveNewComplaint}>Créer la réclamation</button>
        </div>
      </div>
    </div>
  );
}

function ClientFormModal({ clientModal, setClientModal, closeClientModal, saveClientModal, busySaveClient }) {
  if (!clientModal) return null;
  return (
    <div className="overlay show" onClick={(e) => e.target.classList.contains("overlay") && closeClientModal()}>
      <div className="modal">
        <h2>{clientModal.editingId ? "Modifier le client" : "Nouveau client"}</h2>
        <div className="field">
          <label>Nom du client</label>
          <input
            placeholder="Ex: KOFFI"
            value={clientModal.nom}
            onChange={(e) => {
              const nom = e.target.value;
              setClientModal((m) => ({ ...m, nom, accessCode: computeClientCode(nom, m.telephone) }));
            }}
          />
        </div>
        <div className="field">
          <label>Offre / Prix (ou référence)</label>
          <input placeholder="Ex: 30 Mbps/10 000F" value={clientModal.offre} onChange={(e) => setClientModal({ ...clientModal, offre: e.target.value })} />
        </div>
        <div className="field">
          <label>Téléphone WhatsApp</label>
          <input
            type="tel"
            placeholder="Ex: 90 12 34 56 ou +228 90 12 34 56"
            value={clientModal.telephone}
            onChange={(e) => {
              const telephone = e.target.value;
              setClientModal((m) => ({ ...m, telephone, accessCode: computeClientCode(m.nom, telephone) }));
            }}
          />
          <div style={{ fontSize: 11, color: "var(--text-faint)", marginTop: 6 }}>
            Le code d'accès du client est calculé à partir des 4 derniers chiffres de ce numéro.
          </div>
        </div>
        <div className="field">
          <label>Serveur</label>
          <input placeholder="Ex: Serveur 1" value={clientModal.serveur || ""} onChange={(e) => setClientModal({ ...clientModal, serveur: e.target.value })} />
        </div>
        <div className="field">
          <label>Position</label>
          {clientModal.latitude != null ? (
            <div style={{ fontSize: 12, color: "var(--green)", marginBottom: 8 }}>
              ✓ Position enregistrée ({clientModal.latitude.toFixed(5)}, {clientModal.longitude.toFixed(5)})
            </div>
          ) : (
            <div style={{ fontSize: 12, color: "var(--amber)", marginBottom: 8 }}>
              Aucune position enregistrée pour ce client.
            </div>
          )}
          <button
            type="button"
            className="btn-cancel"
            onClick={() => {
              if (!navigator.geolocation) return;
              navigator.geolocation.getCurrentPosition(
                (pos) => setClientModal((m) => ({ ...m, latitude: pos.coords.latitude, longitude: pos.coords.longitude })),
                () => {},
                { enableHighAccuracy: true, timeout: 10000 }
              );
            }}
          >
            📍 {clientModal.latitude != null ? "Mettre à jour ma position actuelle" : "Capturer ma position actuelle"}
          </button>
        </div>
        <div className="field">
          <label>Date d'expiration</label>
          <DatePickerInput value={clientModal.dateExp} onChange={(e) => setClientModal({ ...clientModal, dateExp: e.target.value })} />
        </div>
        <div className="field">
          <label>Code d'accès client (espace personnel)</label>
          <div style={{ display: "flex", gap: 8 }}>
            <input
              style={{ fontFamily: "var(--mono)", letterSpacing: 2, fontWeight: 700 }}
              value={clientModal.accessCode}
              onChange={(e) => setClientModal({ ...clientModal, accessCode: e.target.value.toUpperCase() })}
            />
            <button
              type="button"
              className="btn-cancel"
              style={{ flex: "0 0 auto", padding: "0 14px" }}
              onClick={() => setClientModal((m) => ({ ...m, accessCode: computeClientCode(m.nom, m.telephone) }))}
            >
              ↻
            </button>
          </div>
          <div style={{ fontSize: 11, color: "var(--text-faint)", marginTop: 6 }}>
            Calculé automatiquement (4 derniers chiffres du téléphone + 2 premières lettres du nom). Transmets-le au client par WhatsApp — modifiable si besoin.
          </div>
        </div>
        <div className="modal-actions">
          <button className="btn-cancel" onClick={closeClientModal}>Annuler</button>
          <button className="btn-save" disabled={busySaveClient} onClick={saveClientModal}>{busySaveClient ? "Enregistrement..." : "Enregistrer"}</button>
        </div>
      </div>
    </div>
  );
}

function MonArgentView({ authUser, fuelExpenses, perdiemExpenses }) {
  const [month, setMonth] = useState(() => new Date().toISOString().slice(0, 7));

  const myFuel = (fuelExpenses || []).filter(
    (f) => authUser && (f.technicienId === authUser.id || f.technicienNom === authUser.nom) && f.createdAt && f.createdAt.startsWith(month)
  );
  const myPerdiem = (perdiemExpenses || []).filter(
    (p) => authUser && (p.personneId === authUser.id || p.personneNom === authUser.nom) && p.createdAt && p.createdAt.startsWith(month)
  );

  const fuelTotal = myFuel.reduce((s, f) => s + (Number(f.montant) || 0), 0);
  const perdiemTotal = myPerdiem.reduce((s, p) => s + (Number(p.montant) || 0), 0);
  const total = fuelTotal + perdiemTotal;

  const combined = [
    ...myFuel.map((f) => ({ id: `f-${f.id}`, date: f.createdAt, motif: `🚗 Carburant → ${f.clientNom || "—"}`, montant: f.montant, status: f.status })),
    ...myPerdiem.map((p) => ({ id: `p-${p.id}`, date: p.createdAt, motif: `💰 Perdiem${p.note ? ` · ${p.note}` : ""}`, montant: p.montant, status: p.status })),
  ].sort((a, b) => (b.date || "").localeCompare(a.date || ""));

  const monthLabel = useMemo(() => {
    const [y, m] = month.split("-").map(Number);
    return new Date(y, m - 1, 1).toLocaleDateString("fr-FR", { month: "long", year: "numeric" });
  }, [month]);

  return (
    <div className="view active">
      <div className="chart-card">
        <div className="ctitle">MON ARGENT — {monthLabel.toUpperCase()}</div>
        <div className="field">
          <label>Choisir un mois</label>
          <input
            type="month"
            value={month}
            onChange={(e) => setMonth(e.target.value)}
            style={{ padding: "10px 12px", borderRadius: 9, border: "1px solid var(--line)", background: "var(--bg-card)", color: "var(--text)" }}
          />
        </div>
        <div className="stats" style={{ marginTop: 14 }}>
          <div className="stat ok"><div className="n">{fmtFCFA(total)}</div><div className="l">Total du mois</div></div>
          <div className="stat attention"><div className="n">{fmtFCFA(fuelTotal)}</div><div className="l">Carburant ({myFuel.length})</div></div>
          <div className="stat expire"><div className="n">{fmtFCFA(perdiemTotal)}</div><div className="l">Perdiem ({myPerdiem.length})</div></div>
        </div>
      </div>

      <div className="chart-card">
        <div className="ctitle">DÉTAIL DU MOIS ({combined.length})</div>
        {combined.length === 0 && <div className="empty">Rien reçu ce mois-ci.</div>}
        {combined.map((item) => (
          <div key={item.id} className="rah-item">
            <span className="rah-date">{item.date ? new Date(item.date).toLocaleDateString("fr-FR") : ""}</span>
            <span>{item.motif}</span>
            <span className={`badge ${item.status === "paye" ? "OK" : "ATTENTION"}`}>
              {fmtFCFA(item.montant)} · {item.status === "paye" ? "Versé" : "En attente"}
            </span>
          </div>
        ))}
      </div>
    </div>
  );
}

